import{_ as e,o as a,c as d,ak as r}from"./chunks/framework.DxrHb2fb.js";const u=JSON.parse('{"title":"XiHan.UI 视图组件","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1789870698000}'),o={name:"introduction.md"};function i(n,t,c,h,l,s){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="xihan-ui-视图组件" tabindex="-1">XiHan.UI 视图组件 <a class="header-anchor" href="#xihan-ui-视图组件" aria-label="Permalink to &quot;XiHan.UI 视图组件&quot;">​</a></h1><p>XiHan.UI 是一套框架无关的组件库：状态机与无障碍逻辑位于无头内核，每个前端框架只有一层薄适配器。</p><p>当前提供 <strong>134 个组件</strong>，每个组件都有无头内核、Vue 组件、React 组件、自定义元素与默认皮肤。各层同源，行为由内核唯一定义，三个适配器负责接入各自的渲染与事件机制。</p><h2 id="与常见组件库的区别" tabindex="-1">与常见组件库的区别 <a class="header-anchor" href="#与常见组件库的区别" aria-label="Permalink to &quot;与常见组件库的区别&quot;">​</a></h2><p>多数组件库把行为与某个框架的组件模型绑定在一起：更换框架需要整套重写，无障碍与键盘交互是重写中最容易丢失的部分。XiHan.UI 将这两层分离：</p><table tabindex="0"><thead><tr><th>层</th><th>包</th><th>职责</th></tr></thead><tbody><tr><td>适配器</td><td><code>@xihan-ui/vue</code>、<code>@xihan-ui/react</code>、<code>@xihan-ui/web-components</code></td><td>将同一份属性和行为接到各自宿主</td></tr><tr><td>无头内核</td><td><code>@xihan-ui/headless</code></td><td>解剖、状态机与 <code>connect</code></td></tr><tr><td>原语</td><td><code>@xihan-ui/core</code>、<code>position</code>、<code>motion</code>、<code>pointer</code></td><td>运行时、定位、动效与指针会话</td></tr><tr><td>表现</td><td><code>@xihan-ui/tokens</code>、<code>@xihan-ui/styles</code></td><td>共享令牌与纯 CSS 皮肤</td></tr></tbody></table><p>由此带来四条可验证的性质：</p><ul><li>同一份行为，三种宿主。Vue、React 与自定义元素共享状态机和 <code>connect</code>；文档站提供对应框架示例，覆盖情况由示例门禁核对。</li><li>样式与逻辑解耦。皮肤只识别 <code>data-scope</code> / <code>data-part</code> / <code>data-*</code> 状态属性，不识别框架，也不识别类名。整体更换皮肤不需要修改 JS。</li><li>无障碍是判据。每个组件都有一份机读的键盘规格表（共 672 条），它同时是测试的分母：用例少覆盖一条即判套件失败。</li><li>依赖面收敛。全部库包的运行时第三方依赖只有一个（<code>@internationalized/date</code>，仅日期族使用）。定位、代码着色、Web Components 响应式基类均为自研。</li></ul><h2 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>入口</th></tr></thead><tbody><tr><td>了解整体架构</td><td><a href="./overview">架构总览</a></td></tr><tr><td>接入现有项目</td><td><a href="./installation">安装与接入</a></td></tr><tr><td>编写第一个组件</td><td><a href="./quickstart">快速上手</a></td></tr><tr><td>查询组件的部件与键盘支持</td><td><a href="./components/">组件总览</a></td></tr><tr><td>修改主题与皮肤</td><td><a href="./guide/theme">设计令牌与主题</a>、<a href="./guide/styling">皮肤与样式分层</a></td></tr><tr><td>使用 Vue / React / 原生自定义元素</td><td><a href="./adapters/vue">Vue 适配器</a>、<a href="./adapters/react">React 适配器</a>、<a href="./adapters/web-components">Web Components 适配器</a></td></tr><tr><td>构建 AI 对话界面</td><td><a href="./guide/ai">AI 协议内核</a></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>源码仓库：<a href="https://github.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://gitee.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">Gitee</a> · <a href="https://gitcode.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitCode</a></li><li>同生态的另外两个仓库：<a href="https://framework.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.Framework 开发框架</a>、<a href="https://basicapp.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.BasicApp 基础应用</a></li></ul><div class="tip custom-block"><p class="custom-block-title">与 XiHan.BasicApp 的关系</p><p>XiHan.BasicApp 的前端构建于 XiHan.UI 之上：自 BasicApp v4.0.0 起整体使用本库重建，是组件库在真实业务中的第一个大体量消费方。BasicApp 的前端约定见<a href="https://basicapp.docs.xihanfun.com/frontend/introduction" target="_blank" rel="noreferrer">基础应用前端手册</a>。</p></div>',13)])])}const f=e(o,[["render",i]]);export{u as __pageData,f as default};
